# SPDX-License-Identifier: MIT
# A media player for LVGL apps on Linux boards: gst-play-1.0 (GStreamer) runs in the background
# through linuxproc.Process and is driven with its keyboard keys. It plays files and http:// streams.
# One process per track: at the end of a track the next one starts.
#
# In the LVGL MPY Studio simulator there is no Linux: a stand-in "plays" silent 30-second tracks,
# so the GUI can be designed and tried without a board.

import time

try:
    import linuxproc
except ImportError:
    linuxproc = None

# GStreamer audio output: None for the default (ALSA, the first sound card), or for example
# "fakesink sync=true" to run without a sound card. The environment variable MPY_AUDIO_SINK sets
# it without changing the code.
try:
    import os

    SINK = os.getenv("MPY_AUDIO_SINK")
except (ImportError, AttributeError):
    SINK = None


def _seconds(text):
    # "0:01:02.5" -> 62.5; None for what is not a time
    parts = text.split(":")
    if len(parts) != 3:
        return None
    try:
        return int(parts[0]) * 3600 + int(parts[1]) * 60 + float(parts[2])
    except ValueError:
        return None


class Player:
    # live=True for radio streams: no duration, and the simulator stand-in plays without end.
    def __init__(self, live=False):
        self.live = live
        self.uris = []
        self.index = -1
        self.position = 0.0
        self.duration = None  # None for a live stream
        self.paused = False
        self.volume = 100
        self.playing = False
        self.error = None
        self._last_error = None
        self.process = None
        self._pending = b""
        self._keys = []
        self._key_at = 0
        self._started = 0

    # --- control -------------------------------------------------------------------------------

    def play(self, uris, index=0):
        self.uris = list(uris)
        self._start(index)

    def toggle_pause(self):
        if self.playing:
            self.paused = not self.paused
            self._key(b" ")

    def next(self):
        if self.uris:
            self._start((self.index + 1) % len(self.uris))

    def previous(self):
        if self.uris:
            # After 3 s, the first press goes back to the start of the track, as on most players.
            self._start(self.index if self.position > 3 else (self.index - 1) % len(self.uris))

    def volume_up(self):
        self._set_volume(self.volume + 10)

    def volume_down(self):
        self._set_volume(self.volume - 10)

    def stop(self):
        if self.process:
            self.process.close()
            self.process = None
        self.playing = False
        self.paused = False
        self.position = 0.0

    # --- to call from an LVGL timer, about 5 times a second --------------------------------------

    def update(self):
        if not self.playing:
            return
        if self.process is None:
            self._simulate()
            return
        if self._keys and time.ticks_diff(time.ticks_ms(), self._key_at) >= 150:
            # One key per read of the player: two keys in one read are ignored as an unknown sequence.
            self.process.write(self._keys.pop(0))
            self._key_at = time.ticks_ms()
        self._pending += self.process.read()
        lines = self._pending.replace(b"\r", b"\n").split(b"\n")
        self._pending = lines.pop()
        for line in lines + [self._pending]:
            self._parse(line.strip())
        status = self.process.poll()
        if status is not None:
            self.process.close()
            self.process = None
            self.playing = False
            if status != 0 or self.duration is None:
                # No sound card, a missing file, a stream that does not answer: say so and stop.
                self.error = self._last_error or "player stopped (%d)" % status
            else:
                self.next()  # the track ended

    # --- inside ------------------------------------------------------------------------------------

    def _start(self, index):
        self.stop()
        self.index = index
        self.position = 0.0
        self.duration = None
        self._pending = b""
        self._keys = []
        self._started = time.ticks_ms()
        self.playing = True
        self.error = None
        self._last_error = None
        if linuxproc is None:
            self.duration = None if self.live else 30.0
            return
        argv = ["gst-play-1.0", "--volume=%.2f" % (self.volume / 100)]
        if SINK:
            argv.append("--audiosink=" + SINK)
        uri = self.uris[index]
        argv.append(uri)
        self.process = linuxproc.Process(argv)

    def _key(self, key):
        if self.process:
            self._keys.append(key)

    def _set_volume(self, volume):
        # gst-play changes the volume by 5% with the arrow keys (+ and - change the speed).
        volume = max(0, min(volume, 100))
        steps = (volume - self.volume) // 5
        self.volume = volume
        for _ in range(abs(steps)):
            self._key(b"\x1b[A" if steps > 0 else b"\x1b[B")

    def _parse(self, line):
        if line.startswith(b"ERROR debug information"):
            pass  # the source location in GStreamer, after the message that matters
        elif line.startswith(b"ERROR") or line.startswith(b"WARNING"):
            self._last_error = line.decode("utf-8", "ignore")[:80]
        elif line.startswith(b"Volume: ") and line.endswith(b"%"):
            try:
                self.volume = int(line[8:-1])
            except ValueError:
                pass
        elif b" / " in line and line[:1].isdigit():
            now, _, total = line.partition(b" / ")
            position = _seconds(now.decode())
            if position is not None:
                self.position = position
            total = total.split(b" ")[0].decode()
            duration = _seconds(total)
            # Live streams report no duration, or one of 99:99:99 and more.
            self.duration = duration if duration is not None and duration < 360000 else None

    def _simulate(self):
        if not self.paused:
            self.position = time.ticks_diff(time.ticks_ms(), self._started) / 1000
        else:
            self._started = time.ticks_add(time.ticks_ms(), -int(self.position * 1000))
        if self.duration is not None and self.position >= self.duration:
            self.next()

# SPDX-License-Identifier: MIT
# The web radio app: stations from stations.txt (or the built-in list), streams played by player.
# The Find page fills stations.txt from the Radio Browser catalogue (radio_find): a country, one of
# its regions, a language, a genre; the stations found are added to the list or replace it.

import time

import lvgl as lv

import player
import radio_find as find

try:
    import mpy_wifi  # on a Linux board; the network comes from settings.json (the Settings app)
except ImportError:
    mpy_wifi = None
try:
    import mpy_settings  # the last search, remembered in settings.json, section "radio"
except ImportError:
    mpy_settings = None

ACCENT = lv.color_hex(0xE0742F)
ROW = lv.color_hex(0x1E2633)
# Name and MP3 stream address. Your own list goes in stations.txt next to main.py (on a Linux board
# /usr/local/mpy/fs/stations.txt), one station per line: Name|http://address
STATIONS = [
    ("Radio Paradise", "http://stream.radioparadise.com/mp3-128"),
    ("Radio Swiss Jazz", "https://stream.srg-ssr.ch/m/rsj/mp3_128"),
    ("FIP", "http://icecast.radiofrance.fr/fip-midfi.mp3"),
]
STATIONS_FILE = "stations.txt"
MAX_STATIONS = 500

_ui = None
_player = player.Player(live=True)
_stations = []
_rows = []
_shown = None
_network_job = None
_online = True
_checked = 0
_started = False
_saved = None  # the list saved by the Find page (also where the simulator keeps it)
_listed = None  # the stations the list on the screen shows
# The Find page
_jobs = {}  # what is being downloaded: "countries", "regions", "languages", "search"
_countries = []  # (name, code)
_regions = []
_languages = []
_found = []
_choice = {}


def _clock(seconds):
    seconds = int(seconds)
    return "%d:%02d:%02d" % (seconds // 3600, seconds // 60 % 60, seconds % 60)


def _row_font():
    # List rows follow the screen: bigger letters on an 800x480 screen than on a 480x272 one.
    height = lv.display_get_default().get_vertical_resolution()
    return lv.font_montserrat_24 if height >= 400 else lv.font_montserrat_14


def _caption(button, text):
    button.get_child(0).set_text(text)


def load_stations():
    if _saved is not None:
        return _saved
    try:
        with open(STATIONS_FILE) as source:
            found = []
            for line in source:
                name, _, url = line.strip().partition("|")
                if name and url.startswith(("http://", "https://")):
                    found.append((name.strip(), url.strip()))
            if found:
                return found
    except OSError:
        pass
    return STATIONS


def save_stations(stations):
    # Through a temporary file, so a power cut leaves either the old list or the new one.
    import os

    global _saved
    _saved = list(stations) or STATIONS
    with open(STATIONS_FILE + ".tmp", "w") as target:
        for name, url in stations:
            target.write("%s|%s\n" % (name, url))
    os.rename(STATIONS_FILE + ".tmp", STATIONS_FILE)


def start(ui):
    # The main page, at start and back from the Find page.
    global _ui, _network_job, _started
    _ui = ui
    if not _started:
        _started = True
        if mpy_wifi is not None:
            try:
                _network_job = mpy_wifi.ensure()  # connects to the Wi-Fi of settings.json if needed
            except (OSError, ValueError) as error:
                print("radio: Wi-Fi:", error)
        lv.screen_active().set_style_bg_color(lv.color_hex(0x121820), 0)
        _caption(ui.prev_button, lv.SYMBOL.PREV)
        _caption(ui.next_button, lv.SYMBOL.NEXT)
        _caption(ui.play_button, lv.SYMBOL.PLAY)
        _caption(ui.volume_down, lv.SYMBOL.VOLUME_MID)
        _caption(ui.volume_up, lv.SYMBOL.VOLUME_MAX)
        _caption(ui.find_button, lv.SYMBOL.PLUS)
        ui.station_list.set_style_border_width(0, 0)
        ui.station_list.set_style_radius(10, 0)
        ui.station_list.set_style_pad_all(4, 0)
        ui.station_list.set_style_pad_row(4, 0)
    _fill_list()


def _fill_list():
    global _stations, _listed, _shown
    _stations = load_stations()
    if _stations == _listed:
        return
    _listed = _stations
    _shown = None
    # A new list while a station plays: the same station, at its new place, or silence.
    urls = [url for _name, url in _stations]
    if _player.uris:
        current = _player.uris[_player.index] if 0 <= _player.index < len(_player.uris) else None
        if current in urls:
            _player.uris = urls
            _player.index = urls.index(current)
        else:
            _player.stop()
            _player.uris = urls
            _player.index = -1
    _ui.station_list.clean()
    _rows.clear()
    for index, (name, _url) in enumerate(_stations):
        row = lv.button(_ui.station_list)
        row.set_width(lv.pct(100))
        row.set_style_bg_color(ROW, 0)
        row.set_style_shadow_width(0, 0)
        label = lv.label(row)
        label.set_text(lv.SYMBOL.AUDIO + "  " + name)
        label.set_style_text_font(_row_font(), 0)
        label.set_long_mode(lv.label.LONG_MODE.DOTS)
        label.set_width(lv.pct(100))
        row.add_event_cb(lambda e, i=index: tune(i), lv.EVENT.CLICKED, None)
        _rows.append(row)
    show()


def tune(index):
    _player.play([url for _name, url in _stations], index)
    show()


def toggle():
    # A live stream is stopped, not paused: play starts it again from now.
    if _player.playing:
        _player.stop()
    elif _stations:
        tune(max(_player.index, 0))
    show()


def next_station():
    _player.next()
    show()


def previous_station():
    if _player.uris:
        tune((_player.index - 1) % len(_player.uris))


def volume_up():
    _player.volume_up()
    show()


def volume_down():
    _player.volume_down()
    show()


def tick():
    global _network_job, _online, _checked
    if _jobs:
        _poll_jobs()
    if _network_job is not None and _network_job.poll() is not None:
        _network_job = None
    if mpy_wifi is not None and time.ticks_diff(time.ticks_ms(), _checked) >= 2000:
        _checked = time.ticks_ms()
        _online = mpy_wifi.online()
    _player.update()
    show()


def show():
    global _shown
    if _ui is None:
        return
    p = _player
    if p.index != _shown and 0 <= p.index < len(_stations):
        _shown = p.index
        _ui.station.set_text(_stations[p.index][0])
        for index, row in enumerate(_rows):
            row.set_style_bg_color(ACCENT if index == p.index else ROW, 0)
        _rows[p.index].scroll_to_view(True)
    _caption(_ui.play_button, lv.SYMBOL.STOP if p.playing else lv.SYMBOL.PLAY)
    if not _online and not p.playing:
        _ui.status.set_text("No internet: connecting..." if _network_job else "No internet: set up Wi-Fi in Settings")
    elif p.error:
        _ui.status.set_text(p.error)
    elif p.playing and p.position > 0:
        _ui.status.set_text("On air  " + _clock(p.position))
    elif p.playing:
        _ui.status.set_text("Connecting...")
    elif p.index >= 0:
        _ui.status.set_text("Stopped")
    _ui.volume.set_text("Volume %d%%" % p.volume)


# --- The Find page: stations from the Radio Browser catalogue


def open_find():
    _ui.load_page(_ui.PAGE_FIND)


def back():
    _ui.load_page(_ui.PAGE_MAIN)


def _dark(dropdown):
    dropdown.get_list().set_style_bg_color(lv.color_hex(0x1E2633), 0)
    dropdown.get_list().set_style_text_color(lv.color_hex(0xFFFFFF), 0)
    dropdown.get_list().set_style_max_height(lv.display_get_default().get_vertical_resolution() * 2 // 3, 0)


def _options(dropdown, first, names, chosen):
    dropdown.set_options("\n".join([first] + names))
    dropdown.set_selected(names.index(chosen) + 1 if chosen in names else 0)


def _say(text):
    _ui.find_status.set_text(text)


def start_find(ui):
    global _choice
    if not _choice:
        lv.screen_active().set_style_bg_color(lv.color_hex(0x121820), 0)
        for dropdown in (ui.country, ui.region, ui.language, ui.genre):
            _dark(dropdown)
        _choice = dict((mpy_settings.get("radio") if mpy_settings else None) or {})
        _choice.setdefault("country", "")
    _options(ui.genre, find.GENRES[0], list(find.GENRES[1:]), _choice.get("genre"))
    if not _countries:
        ui.country.set_options("Loading...")
        _jobs["countries"] = find.countries()
    if not _languages:
        ui.language.set_options("Loading...")
        _jobs["languages"] = find.languages()
    if _countries and not _regions and _choice.get("country"):
        _start_regions()
    if not _regions:
        ui.region.set_options(find.ANY_REGION)
    _show_found()


def _start_regions():
    name = dict((code, n) for n, code in _countries).get(_choice.get("country"))
    _regions.clear()
    _ui.region.set_options(find.ANY_REGION)
    if name:
        _ui.region.set_options("Loading...")
        _jobs["regions"] = find.regions(name)


def _poll_jobs():
    for kind in list(_jobs):
        result = _jobs[kind].poll()
        if result is None:
            continue
        del _jobs[kind]
        data, error = result
        if error:
            _say("Catalogue: " + error)
            if kind == "search":
                _ui.search_button.remove_state(lv.STATE.DISABLED)
            continue
        if kind == "countries":
            _countries[:] = find.country_list(data)
            codes = [code for _name, code in _countries]
            _options(_ui.country, find.ANY_COUNTRY, [n for n, _c in _countries],
                     _countries[codes.index(_choice["country"])][0] if _choice["country"] in codes else None)
            if _choice["country"] in codes:
                _start_regions()
        elif kind == "regions":
            _regions[:] = find.region_list(data)
            _options(_ui.region, find.ANY_REGION, _regions, _choice.get("region"))
        elif kind == "languages":
            _languages[:] = find.language_list(data)
            _options(_ui.language, find.ANY_LANGUAGE, _languages, _choice.get("language"))
        elif kind == "search":
            _found[:] = find.station_list(data)
            _ui.search_button.remove_state(lv.STATE.DISABLED)
            _show_found()


def _show_found():
    for button in (_ui.add_button, _ui.replace_button):
        if _found:
            button.remove_state(lv.STATE.DISABLED)
        else:
            button.add_state(lv.STATE.DISABLED)
    if "search" in _jobs:
        return
    if _found:
        _say("%d stations found, the most listened first" % len(_found))
    elif not _jobs:
        _say("Choose, then Search")


def country_changed():
    index = _ui.country.get_selected()
    if not _countries:
        return
    _choice["country"] = _countries[index - 1][1] if index > 0 else ""
    _choice["region"] = ""
    _start_regions()


def _selected(dropdown, names):
    index = dropdown.get_selected()
    return names[index - 1] if 0 < index <= len(names) else ""


def search():
    _choice["region"] = _selected(_ui.region, _regions)
    _choice["language"] = _selected(_ui.language, _languages)
    _choice["genre"] = _selected(_ui.genre, list(find.GENRES[1:]))
    if mpy_settings:
        try:
            mpy_settings.update("radio", _choice)
        except OSError:
            pass
    _found.clear()
    _jobs["search"] = find.search(_choice["country"], _choice["region"], _choice["language"],
                                  _choice["genre"])
    _ui.search_button.add_state(lv.STATE.DISABLED)
    _show_found()
    _say("Searching...")


def _keep(stations):
    try:
        save_stations(stations[:MAX_STATIONS])
    except OSError as error:
        print("radio: stations.txt:", error)
    _found.clear()
    back()


def add_found():
    # The stations found after those already in the list, each address once.
    stations = list(load_stations())
    known = set(url for _name, url in stations)
    stations += [s for s in _found if s[1] not in known]
    _keep(stations)


def replace_found():
    _keep(list(_found))

# SPDX-License-Identifier: MIT
# Stations from Radio Browser (https://www.radio-browser.info): a free, open catalogue of tens of
# thousands of internet radios, no account and no key. The countries, the regions of a country and
# the languages come from it; a search returns the most listened stations that match, at most
# LIMIT, those the board can play (MP3, AAC, Ogg).
#
# On a Linux board curl downloads in the background (mpy_wifi.Job): start a request, then call
# poll() from a timer until it returns the data. In the Studio simulator demo data comes back.

import json
import os

try:
    import mpy_wifi
except ImportError:
    mpy_wifi = None

API = "https://all.api.radio-browser.info/json/"
LIMIT = 300
CODECS = ("MP3", "AAC", "AAC+", "OGG")
GENRES = ("Any genre", "pop", "rock", "jazz", "classical", "news", "talk", "dance", "electronic",
          "oldies", "80s", "hits", "chillout", "lounge", "folk", "country", "sport", "christian")
ANY_COUNTRY = "Any country"
ANY_REGION = "Any region"
ANY_LANGUAGE = "Any language"

CURL_ERRORS = {
    6: "name not found: is the network up?",
    7: "cannot connect to the catalogue",
    28: "the catalogue did not answer in time",
    60: "certificate refused: is the clock set?",
}

# The board's fonts have ASCII only: accented letters lose the accent, other scripts are left out.
_PLAIN = {}
for _letters, _plain in (
        ("àáâãäåāăą", "a"), ("ÀÁÂÃÄÅĀĂĄ", "A"), ("çćĉċč", "c"), ("ÇĆĈĊČ", "C"), ("ďđ", "d"),
        ("ĎĐ", "D"), ("èéêëēĕėęě", "e"), ("ÈÉÊËĒĔĖĘĚ", "E"), ("ĝğġģ", "g"), ("ĜĞĠĢ", "G"),
        ("ìíîïĩīĭįı", "i"), ("ÌÍÎÏĨĪĬĮİ", "I"), ("ĺļľŀł", "l"), ("ĹĻĽĿŁ", "L"), ("ñńņň", "n"),
        ("ÑŃŅŇ", "N"), ("òóôõöøōŏő", "o"), ("ÒÓÔÕÖØŌŎŐ", "O"), ("ŕŗř", "r"), ("ŔŖŘ", "R"),
        ("śŝşšș", "s"), ("ŚŜŞŠȘ", "S"), ("ţťŧț", "t"), ("ŢŤŦȚ", "T"), ("ùúûüũūŭůűų", "u"),
        ("ÙÚÛÜŨŪŬŮŰŲ", "U"), ("ýÿ", "y"), ("ÝŸ", "Y"), ("źżž", "z"), ("ŹŻŽ", "Z"),
        ("‘’´`", "'"), ("“”«»", '"'), ("–—", "-")):
    for _c in _letters:
        _PLAIN[_c] = _plain
_PLAIN.update({"ß": "ss", "æ": "ae", "Æ": "AE", "œ": "oe", "Œ": "OE", "…": "...", "|": "/"})


def plain(text):
    out = ""
    dropped = 0
    for c in text:
        if c in _PLAIN:
            out += _PLAIN[c]
        elif " " <= c <= "~":
            out += c
        else:
            dropped += 1
    out = " ".join(out.split())
    # A name mostly in another script says nothing once its letters are gone.
    return out if out and dropped <= len(out) // 2 else ""


def _quote(text):
    out = ""
    for byte in text.encode():
        c = chr(byte)
        out += c if (byte < 128 and (c.isalpha() or c.isdigit())) or c in "-_.~" else "%%%02X" % byte
    return out


class Request:
    # A download in the background, into a file (a search is a few hundred kilobytes: no need to
    # pass them through the pseudo-terminal). poll(): None while it runs, then (data, error).
    _count = 0

    def __init__(self, path, demo):
        self._demo = demo
        self._job = None
        Request._count += 1
        self._file = "/tmp/mpy-radio-%d.json" % Request._count
        if mpy_wifi:
            self._job = mpy_wifi.Job(["curl", "-s", "-f", "-L", "-m", "30", "-A", "lvgl-mpy-radio/1.0",
                                      "-o", self._file, API + path])

    def poll(self):
        if self._job is None:
            return self._demo, None
        if self._job.poll() is None:
            return None
        if self._job.status != 0:
            return None, CURL_ERRORS.get(self._job.status, "no answer (curl %d)" % self._job.status)
        try:
            with open(self._file) as source:
                return json.load(source), None
        except (OSError, ValueError):
            return None, "bad answer from the catalogue"
        finally:
            try:
                os.remove(self._file)
            except OSError:
                pass


def countries():
    return Request("countries?order=name&hidebroken=true", DEMO_COUNTRIES)


def country_list(data):
    # (name, code) of the countries with at least a few stations, by name.
    found = [(plain(c["name"]), c["iso_3166_1"]) for c in data
             if c.get("stationcount", 0) >= 5 and c.get("iso_3166_1")]
    found = [c for c in found if c[0]]
    found.sort(key=lambda c: c[0][4:] if c[0].startswith("The ") else c[0])
    return found


def regions(country):
    return Request("states/%s/?order=stationcount&reverse=true&hidebroken=true" % _quote(country),
                   DEMO_REGIONS)


def region_list(data):
    # The regions (the catalogue's "state") with at least 3 stations, the biggest first. Their
    # names are as the stations' owners wrote them: Lombardia and Lombardy may both appear.
    found = []
    for r in data:
        name = r.get("name", "")
        if r.get("stationcount", 0) >= 3 and plain(name) == name and name not in found:
            found.append(name)
    return found


def languages():
    return Request("languages?order=stationcount&reverse=true&hidebroken=true&limit=80", DEMO_LANGUAGES)


def language_list(data):
    found = [l["name"] for l in data if l.get("stationcount", 0) >= 20 and plain(l["name"]) == l["name"]]
    found.sort()
    return found


def search(country_code=None, region=None, language=None, genre=None):
    query = "stations/search?hidebroken=true&order=clickcount&reverse=true&limit=%d" % LIMIT
    if country_code:
        query += "&countrycode=" + country_code
    if region:
        query += "&state=%s&stateExact=true" % _quote(region)
    if language:
        query += "&language=" + _quote(language)
    if genre:
        query += "&tag=" + _quote(genre)
    return Request(query, DEMO_STATIONS)


def station_list(data):
    # (name, address) of the stations found that the board can play, each address once.
    found = []
    seen = set()
    for s in data:
        url = (s.get("url_resolved") or s.get("url") or "").strip()
        name = plain(s.get("name", ""))
        if not name or not url.startswith(("http://", "https://")) or s.get("codec") not in CODECS:
            continue
        if url in seen:
            continue
        seen.add(url)
        found.append((name, url))
    return found


